// src/context/ClaimContext.jsx
import React, { createContext, useState, useContext } from 'react';
import { api } from '../services/api.js';

const ClaimContext = createContext();

export function ClaimProvider({ children }) {
  const [claims, setClaims] = useState([]);
  const [currentClaim, setCurrentClaim] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchClaim = async (msisdn) => {
    setIsLoading(true);
    setError(null);
    try {
      // Use mock for development, replace with actual API call
      const data = await api.getClaimMock(msisdn);
      setCurrentClaim(data);
      return data;
    } catch (error) {
      console.error('Error fetching claim:', error);
      setError(error.message);
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const addClaim = (claim) => {
    setClaims(prev => [...prev, { ...claim, id: Date.now() }]);
  };

  const updateClaim = (id, updates) => {
    setClaims(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const clearCurrentClaim = () => {
    setCurrentClaim(null);
    setError(null);
  };

  const value = {
    claims,
    currentClaim,
    isLoading,
    error,
    fetchClaim,
    addClaim,
    updateClaim,
    setCurrentClaim,
    clearCurrentClaim
  };

  return (
    <ClaimContext.Provider value={value}>
      {children}
    </ClaimContext.Provider>
  );
}

export function useClaimContext() {
  const context = useContext(ClaimContext);
  if (!context) {
    throw new Error('useClaimContext must be used within a ClaimProvider');
  }
  return context;
}

// Default export for easier imports
export default ClaimContext;
